%%
% compute the AE33 abs coef since only the eBC in microg/m3 are reported
% under X*_A82
% as given by NOAA documentation for AE33
% https://gml.noaa.gov/aero/docs/ae33_sop_20161227.pdf, abs=BC*sigma
sigma=[18.47 14.54 13.14 11.58 10.35 7.77 7.19]; %for the 7 wavelengths with an exponent of -1
MLO_rd.Ba1_A82=MLO_rd.X1_A82.*sigma(1);
MLO_rd.Ba2_A82=MLO_rd.X2_A82.*sigma(2);
MLO_rd.Ba3_A82=MLO_rd.X3_A82.*sigma(3);
MLO_rd.Ba4_A82=MLO_rd.X4_A82.*sigma(4);
MLO_rd.Ba5_A82=MLO_rd.X5_A82.*sigma(5);
MLO_rd.Ba6_A82=MLO_rd.X6_A82.*sigma(6);
MLO_rd.Ba7_A82=MLO_rd.X7_A82.*sigma(7);
%%
